-- Test specs generated by tdd-agent while a Request is executing (docs/integrate/TDD-REQ-TESTSPEC-001). One row per attempt; the row with
-- is_current = 1 is the one the screen shows. Nothing here is read by the code-execution lane: the two lanes share only the trigger.
CREATE TABLE request_test_spec_runs (
    id CHAR(36) PRIMARY KEY,
    tenant_id CHAR(36) NOT NULL,
    request_id CHAR(36) NOT NULL,
    attempt INT NOT NULL DEFAULT 1,
    status VARCHAR(16) NOT NULL CHECK (status IN ('pending','starting','running','completed','blocked','failed','skipped','cancelled')),
    reason_code VARCHAR(96) NOT NULL DEFAULT '',
    reason_message TEXT NOT NULL,
    context_mode VARCHAR(16) NOT NULL DEFAULT '',
    context_ref VARCHAR(64) NOT NULL DEFAULT '',
    context_sha256 VARCHAR(64) NOT NULL DEFAULT '',
    tdd_run_id VARCHAR(64) NOT NULL DEFAULT '',
    feature VARCHAR(128) NOT NULL DEFAULT '',
    summary JSON NOT NULL,
    started_by CHAR(36) NULL,
    started_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    finished_at TIMESTAMP(6) NULL,
    updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    -- 1 for the current attempt, NULL once superseded: NULLs never collide, so the unique key allows one current row per Request.
    is_current TINYINT NULL,
    superseded_at TIMESTAMP(6) NULL,
    lease_owner VARCHAR(255) NOT NULL DEFAULT '',
    lease_until TIMESTAMP(6) NOT NULL DEFAULT '2000-01-01 00:00:01.000000',
    CONSTRAINT fk_request_test_spec_runs_request FOREIGN KEY (request_id) REFERENCES requests(id),
    UNIQUE KEY request_test_spec_runs_one_current (tenant_id, request_id, is_current),
    INDEX request_test_spec_runs_history (tenant_id, request_id, attempt),
    INDEX request_test_spec_runs_active (status, updated_at)
) ENGINE=InnoDB;
